<?php
require_once __DIR__.'/../../includes/functions.php';require_admin();$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$status=(string)($_POST['status']??'');if($id&&in_array($status,['approved','rejected'],true)){db()->prepare('UPDATE product_reviews SET status=? WHERE id=?')->execute([$status,$id]);$notice='Review moderation saved.';}}
$rows=db()->query('SELECT pr.*,p.name AS product_name,u.name AS customer_name FROM product_reviews pr JOIN products p ON p.id=pr.product_id JOIN users u ON u.id=pr.user_id ORDER BY pr.created_at DESC LIMIT 200')->fetchAll();$adminTitle='Reviews · Yucca Fabrics';require __DIR__.'/../../includes/admin-header.php';
?>
<h1 class="font-serif text-4xl">Customer reviews</h1><?php if($notice): ?><p class="mt-4 rounded bg-green-50 p-3 text-sm text-green-800"><?= e($notice) ?></p><?php endif; ?><div class="mt-6 space-y-3"><?php if(!$rows): ?><p class="bg-white p-6 text-sm text-gray-600">There are no reviews to moderate.</p><?php endif; ?><?php foreach($rows as $row): ?><article class="flex flex-wrap items-start justify-between gap-5 bg-white p-5"><div><p class="text-xs uppercase tracking-widest text-sage"><?= e($row['product_name']) ?></p><p class="mt-2 text-clay"><?= str_repeat('★',(int)$row['rating']) ?></p><?php if($row['title']): ?><h2 class="mt-2 font-serif text-xl"><?= e($row['title']) ?></h2><?php endif; ?><p class="mt-2 max-w-2xl text-sm leading-6"><?= e($row['review']) ?></p><p class="mt-3 text-xs text-gray-500"><?= e($row['customer_name']) ?> · <?= e(date('M j, Y',strtotime($row['created_at']))) ?> · <?= e($row['status']) ?></p></div><form method="post" class="flex gap-2"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><?php foreach(['approved','rejected'] as $status): ?><button name="status" value="<?= e($status) ?>" class="rounded-full border border-forest px-4 py-2 text-xs"><?= e(ucfirst($status)) ?></button><?php endforeach; ?></form></article><?php endforeach; ?></div>
<?php require __DIR__.'/../../includes/admin-footer.php'; ?>
